[Form]
public class TFMPageConfigurator extends FormRun
{
    FormCommandButtonControl        saveButton;
    TFMPageConfiguratorFormClass    pageConfiguratorClass;
    QueryBuildRange				    qbr;
    QueryBuildRange				    qbrMenuItems;
    TFMPageID                       pageId;
    TFMPageXSDParser			    parser;

}

 public void run()
{
    URLUtility              urlUtil = new URLUtility();
    TFMPage                 page;        
    SysDictClass            dc;
    TFMPageTypeAttribute    pageAttr;

    if (element.args().caller() && (element.args().caller().name() == formStr(TFMPageOverview) || element.args().caller().name() == formStr(TFMNewPageFromProcess) || element.args().caller().name() == formStr(TFMProcessOverview) || SysTest::hasMethod(element.args().caller(), formMethodStr(TFMPageOverview, getCurrentPage))))
    {
        page = element.args().caller().getCurrentPage();
        pageId = page.parmId();
    }
    else
    {
        pageId = urlUtil.getQueryParamValue('PageId');
    }


    pageConfiguratorClass = new TFMPageConfiguratorFormClass(pageId, TFMPageMenuItems_ds, TFMPageMenuItems_MenuPageID);

    if(!pageConfiguratorClass || !pageConfiguratorClass.currentPage())
    {
        info("@TFM:Unabletoopentheconfiguratorforth");
        return;
    }
    super();
    this.updatePageClass();

    element.design().caption(strFmt("@SYS109730", "@TFM:PageConfigurator", pageId));

    TFMDeltaPages_ds.queryBuildDataSource().addRange(fieldNum(TFMDeltaPages,Name)).value(pageId);
    TFMDeltaPages_ds.executeQuery();

    saveButton = this.control(this.controlId('systemdefinedsavebutton')) as FormCommandButtonControl;

    dc = new SysDictClass(classIdGet(page));
    pageAttr = dc.getAttribute(classStr(TFMPageTypeAttribute));

    OrderLinesPinnableValues.visible(OrderLinesPinnableValues.enabled(pageAttr.parmPageType() == 'OrderLines'));

    TFMPage_TitleTranslated.text(TFMListVisualization::getMenuTitle(element.getCurrentPage().parmTitle()));
}

