public void updatePageClass()
{
    TFMPage pageClass = pageConfiguratorClass.currentPage();
    TFMPage_Title.text(pageClass.parmTitle());
    TFMPage_Icon.text(pageClass.parmIcon());
    TFMPage_Description.text(pageClass.parmDescription());
    this.updatePageIconOnForm();

    Offline.visible(pageClass.getConfiguration().hasOfflineOptions());

    XmlViewer.visible(true);
}

public void CloseLookupForMenuItems(str selectedMenuItemId = '')
{
    if(!selectedMenuItemId)
    {
        // when the lookup form closes then set the selected item back to what is was before.
        pageConfiguratorClass.setActiveMenuItem(pageConfiguratorClass.parmLastSelectedMenuItemId());
    }
}

public void updatePageIconOnForm()
{
    TFMGraphicsHelper::setImageHtmlWithWidth(element.getCurrentPage().parmIcon(), HtmlViewerIcon, 120); //TODO: Use the TFMMediaProvider getMediaForHtml
}

private void LookupResource()
{
    Args    args = new Args();
    Object  formRun;
    FormStringControl formControl = element.PageMenuItemGrid_MenuPageIconString;
    args.name(formStr(TFMResourceLookup));
    args.caller(formControl);
    formRun = classfactory.formRunClass(args);
    formRun.init();
    formControl.performFormLookup(formRun);
}

private void populateAdditionalMenuItemProperties(FormGroupControl _formGroupControl, Map _xsdNodesForCurrentMenuItem, str _pageCommandKey, Set _addedFields)
{
    anytype                                 methodValue;
    MapEnumerator							xsdNodesForMenuItemEnum;
    TFMPage                                 pageClass;


    if(_xsdNodesForCurrentMenuItem)
    {
        xsdNodesForMenuItemEnum = _xsdNodesForCurrentMenuItem.getEnumerator();
        while (xsdNodesForMenuItemEnum.moveNext())
        {
            str pageCommandKeyAndFieldName = _pageCommandKey + '/' + xsdNodesForMenuItemEnum.currentKey();
            if(!_addedFields.in(pageCommandKeyAndFieldName) && !TFMPageMenuItemsHelper::isMenuItemElement( xsdNodesForMenuItemEnum.currentKey()))
            {
                // add the field from the documentation that was not in the parmMethods.
                Map fieldValue = xsdNodesForMenuItemEnum.currentValue();
                if(fieldValue)
                {
                    str typeStr = fieldValue.lookup('type'); // find the type and convert it to a X++ type
                    if(typeStr)
                    {
                        //boolean converted;
                        Types t;
                        ExtendedTypeId edt;
                        [t, edt] = TFMFormHelper::convertXsdStringTypeToTypes(typeStr);

                        List enumValuesValuesList;
                        if(fieldValue.exists('enumValues'))
                        {
                            List enumValuesList;
                            str enumValuesStr = fieldValue.lookup('enumValues');
                            enumValuesList = TFMHelper::strSplit(enumValuesStr,'|');
                            ListEnumerator enumValuesListEnum = enumValuesList.getEnumerator();
                            enumValuesValuesList = new List(Types::String);
                            while(enumValuesListEnum.moveNext())
                            {
                                enumValuesValuesList.addEnd(conPeek(TFMHelper::strSplit(enumValuesListEnum.current(),'¤').pack(), 4));
                            }
                        }
                        pageClass = this.getCurrentPage();
                        methodValue = TFMPageConfigParms::getValue(pageClass.getConfiguration().parmName(), classId2Name(classIdGet(pageClass.getConfiguration())), pageCommandKeyAndFieldName, '');
                        TFMFormHelper::type2FormControl(_formGroupControl, t, edt, pageCommandKeyAndFieldName, (methodValue) ? methodValue : fieldValue.lookup('default'), xsdNodesForMenuItemEnum.currentKey(), methodStr(TFMPageConfiguratorFormClass, control_modified), pageConfiguratorClass, '' ,fieldValue.lookup('annotation'), enumValuesValuesList);
                    }
                }
            }
        }
    }
}

private void clearAttributes()
{
    while (FormGroupControlMenuItemsAttributesCol1.controlCount())
    {
        FormGroupControlMenuItemsAttributesCol1.formRun().design().removeControl(FormGroupControlMenuItemsAttributesCol1.controlNum(1).id());
    }
    while (FormGroupControlMenuItemsAttributesCol2.controlCount())
    {
        FormGroupControlMenuItemsAttributesCol2.formRun().design().removeControl(FormGroupControlMenuItemsAttributesCol2.controlNum(1).id());
    }
}

