public int active()
{
    int ret = super();

    TFMPageConfigurationAttributeAttribute	configAttr;
    TFMPageActionAttribute                  actionAttr;
    SysDictMethod			                DM;
    SetEnumerator                           methodSet;
    anytype                                 methodValue;
    Map										xsdDocumentationForCurrentMenuItem;
    Map										xsdNodesForCurrentMenuItem;
    Map										xsdNodesForCurrentMenuItemRow2;
    Set                                     parmMethodsOnConfigurationClass = new Set(Types::String);
    str										xPath;
    str                                     xPathAndKey;
    Set										addedFields;
    str                                     lastPartOfXPath;
    str                                     rootXPath = 'application/pages/page/';
    str                                     helpText;
    XmlElement                              helpTextElem;
    str                                     pageCommandKey;
    TFMPage                                 pageClass;

    if(!element.MenuItems.IsActivePage())
    {
        return ret;
    }

    pageClass = element.getCurrentPage();

    if(!TFMPageMenuItems || !pageClass)
    {
        return ret;
    }

    parser = TFMPageXsdParserProvider::instance().getEntityImpl();

    FormGroupControlMenuItemsAttributesCol1.columns(1);
    xPath = rootXPath + TFMRegistrationCollector::smallBeginnings(subStr(classId2Name(classIdGet(pageClass.getConfiguration())), strLen(classStr(TFMPage))+1, strLen(classId2Name(classIdGet(pageClass.getConfiguration())))));

    addedFields = new Set(Types::String);
    pageCommandKey = TFMPageMenuItems.MenuPageID;
    pageConfiguratorClass.parmLastSelectedMenuItemId(TFMPageMenuItems.MenuPageID);
    TFMMenuItemsCtrl1.setActiveMenuItemsToJavascript(pageConfiguratorClass.parmLastSelectedMenuItemId());

    // remove controls from attributes
    element.clearAttributes();

    // find documentation for the menu item it self.
    str xPathForMenuItemInXsd;

    switch(TFMPageMenuItems.MenuItemType)
    {
        case TFMPageMenuItemTypes::AdhocAction:
            xPathForMenuItemInXsd = rootXPath + 'actions/adhocRegistration';
            break;
        case TFMPageMenuItemTypes::OpenAction:
            xPathForMenuItemInXsd = rootXPath + 'actions/open';
            break;
        case TFMPageMenuItemTypes::showImage:
            xPathForMenuItemInXsd = rootXPath + 'actions/showImage';
            break;
        case TFMPageMenuItemTypes::OfflinePageMenuItem:
        case TFMPageMenuItemTypes::PageMenuItem:
            if(pageCommandKey == TFMConstants::MenuItemTypeBarcode())
            {
                xPathForMenuItemInXsd = rootXPath + 'typeBarcode';
            }else
            {
                xPathForMenuItemInXsd = xPath + '/' + pageCommandKey;
            }
            break;
        case TFMPageMenuItemTypes::typeBarcode:
            xPathForMenuItemInXsd = rootXPath + 'typeBarcode';
            break;
        default:
    }
    Map xsdDocForMenuItemMap = parser.drillDown(xPathForMenuItemInXsd, false, true);
    lastPartOfXPath = TFMFormHelper::getLastPartOfPath(xPathForMenuItemInXsd);
    if(xsdDocForMenuItemMap.exists(lastPartOfXPath))
    {
        XmlElement xmlDocElement = xsdDocForMenuItemMap.lookup(lastPartOfXPath);
        if(xmlDocElement)
        {
            FormStaticTextControl_description.text(xmlDocElement.InnerText());
        } 
        else
        {
            FormStaticTextControl_description.text('');
        }
    }

    // add all parms methods to the control group.
    parmMethodsOnConfigurationClass = TFMFormLookupHelper::parmMethodsOnClass(classIdGet(pageClass.getConfiguration()));
    methodSet = parmMethodsOnConfigurationClass.getEnumerator();
    while (methodSet.moveNext())
    {
        DM = new SysDictMethod(UtilElementType::ClassInstanceMethod,classIdGet(pageClass.getConfiguration()),methodSet.current());

        configAttr = DM.getAttribute(classStr(TFMPageConfigurationAttributeAttribute));
        if (!configAttr || configAttr.parmXPath() != pageCommandKey)
        {
            continue;
        }

        actionAttr = DM.getAttribute(classStr(TFMPageActionAttribute));
        if(actionAttr)
        {
            lastPartOfXPath = TFMFormHelper::getLastPartOfPath(configAttr.parmXPath());
            if(!TFMPageMenuItemsHelper::isMenuItemElement( configAttr.parmnodeName()))
            {
                //add documentation from xsd.
                xsdDocumentationForCurrentMenuItem = parser.drillDown(xPath + '/' + configAttr.parmXPath(), false, true);

                helpText = '';
                if(xsdDocumentationForCurrentMenuItem && xsdDocumentationForCurrentMenuItem.elements())
                {
                    helpTextElem = xsdDocumentationForCurrentMenuItem.lookup(lastPartOfXPath);
                    if(helpTextElem)
                    {
                        helpText = helpTextElem.innerText();
                    }
                }

                methodValue = TFMPageConfigParms::getValue(pageClass.getConfiguration().parmName(), classId2Name(classIdGet(pageClass.getConfiguration())), DM.name(), '');
                TFMFormHelper::type2FormControl(FormGroupControlMenuItemsAttributesCol1, DM.returnType(), DM.returnId() , DM.name(), methodValue, configAttr.parmnodeName(), methodStr(TFMPageConfiguratorFormClass, control_modified), pageConfiguratorClass, '', helpText);
            }

            addedFields.add(configAttr.parmXPath() + '/' + configAttr.parmnodeName());
        }
    }

    if(TFMPageMenuItems.MenuItemType == TFMPageMenuItemTypes::OpenAction)
    {
        TFMPage pointsToPage = TFMPagesProvider::getAllPages().getPage(TFMPageMenuItems.MenuPageID);

        if( pointsToPage && (pointsToPage.parmType() == TFMConstants::Lookup() || pointsToPage.parmType() == TFMConstants::UnplannedItemRegistration()))
        {
            // only show if the page points to an unplanned or lookup page.
            str suppressReferesName = TFMPageMenuItems.MenuPageID + '/' + TFMConstants::SuppressRefreshAfterSuccessfulPost();
            methodValue = TFMPageConfigParms::getValue(pageClass.getConfiguration().parmName(), classId2Name(classIdGet(pageClass.getConfiguration())), suppressReferesName, '');
            helpText = "@TFM:Supressrefreshingthispagewhenret";
            TFMFormHelper::type2FormControl(FormGroupControlMenuItemsAttributesCol1, extendedTypeNum(NoYesId), extendedTypeNum(NoYesId), suppressReferesName, methodValue, "@TFM:Suppressrefreshaftersuccesfulpos", methodStr(TFMPageConfiguratorFormClass, control_modified), pageConfiguratorClass, '', helpText);
        }

        str automaticTransfer = TFMPageMenuItems.MenuPageID + '/' + TFMConstants::AutomaticValueTransfer();
        methodValue = TFMPageConfigParms::getValue(pageClass.getConfiguration().parmName(), classId2Name(classIdGet(pageClass.getConfiguration())), automaticTransfer, true);
        helpText = "@TFM:automaticValueTransferHelp";
        TFMFormHelper::type2FormControl(FormGroupControlMenuItemsAttributesCol1, extendedTypeNum(NoYesId), extendedTypeNum(NoYesId), automaticTransfer, methodValue, "@TFM:automaticValueTransfer", methodStr(TFMPageConfiguratorFormClass, control_modified), pageConfiguratorClass, '', helpText);
    }

    // add additional properties for the menu item
    if(addedFields)
    {
        xPathAndKey = xPath + '/' + pageCommandKey; //xpath includes the configuration page in the path.

        xsdNodesForCurrentMenuItem = parser.drillDownForAttributes(xPathAndKey);

        if(!xsdNodesForCurrentMenuItem || !xsdNodesForCurrentMenuItem.elements())
        {
            // look in the page element
            xsdNodesForCurrentMenuItem = parser.drillDownForAttributes(rootXPath + pageCommandKey);
        }

        if(!xsdNodesForCurrentMenuItem || !xsdNodesForCurrentMenuItem.elements())
        {
            // look in the actions element
            if(TFMPageMenuItems.MenuItemType == TFMPageMenuItemTypes::AdhocAction)
            {
                xsdNodesForCurrentMenuItem = parser.drillDownForAttributes(rootXPath + 'actions/adhocRegistration');
                xsdNodesForCurrentMenuItemRow2 = parser.drillDownForAttributes(rootXPath + 'actions/adhocRegistration/onSuccessfulPost');
                element.populateAdditionalMenuItemProperties(FormGroupControlMenuItemsAttributesCol2, xsdNodesForCurrentMenuItemRow2, pageCommandKey + '/onSuccessfulPost', addedFields);

            }
            else
            {
                xsdNodesForCurrentMenuItem = parser.drillDownForAttributes(rootXPath + 'actions/' + pageCommandKey);
            }
        }

        element.populateAdditionalMenuItemProperties(FormGroupControlMenuItemsAttributesCol1, xsdNodesForCurrentMenuItem, pageCommandKey, addedFields);

    }
    if (TFMConstants::MenuItemTypeBarcode() == TFMPageMenuItems.MenuPageID)
    {
        //Handle Qualifiers
        FormGroupControlMenuItemsAttributesCol1.columns(4);
        pageConfiguratorClass.populateTypeBarcodePropertiesWithGs1AIs(FormGroupControlMenuItemsAttributesCol1);
    }

    return ret;
}

public display container menuItemIcon(TFMPageMenuItems _record)
