/// <summary>
///
/// </summary>
public void pageActivated()
{
    boolean outputTranslatedValue = FormCheckBoxControl_TranslateLabels.checked(); 

    TFMPageOrderList orderList = element.getCurrentPage() as TFMPageOrderList;
    XML serviceXml = (orderList) ? orderList.getServiceXML() : '';
    XML outputXmlStr;
    XmlDocument pagesRoot = element.getCurrentPage().getXML(pageConfiguratorClass.pagesOnForm);
    XmlElement outputElement;

    outputElement = pagesRoot.createElement('output');
    outputXmlStr = outputElement.innerXml(pagesRoot.getNamedElement('page').xml() + serviceXml);

    if(outputTranslatedValue)
    {
        outputXmlStr = TFMTranslationProvider::replaceAllTranslations(outputXmlStr);
    }

    XmlViewer.parmFormatAsXml('Yes');
    XmlViewer.parmHtml(TFMFormXMLFormatter::htmlColorXML('<output>' + outputXmlStr + '</output>'));
    super();
}

